CREATE TABLE pessoa (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL, email varchar(4000) NOT NULL, matricula varchar(4000) NOT NULL, perfil varchar(4000) NOT NULL, senha_hash varchar(4000), ativo boolean NOT NULL, telefone varchar(4000), endereco varchar(4000), documento varchar(4000), nascimento date);
CREATE TABLE curso (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL);
CREATE TABLE serie (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL);
CREATE TABLE materia (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL);
CREATE TABLE unidade (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL, endereco varchar(4000), telefone varchar(4000));
CREATE TABLE curriculo (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome varchar(4000) NOT NULL, materia_id bigint NOT NULL, carga_horaria integer NOT NULL);
CREATE TABLE turma (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, curso_id bigint NOT NULL, serie_id bigint NOT NULL, ano integer NOT NULL, nome varchar(4000) NOT NULL);
CREATE TABLE disciplina (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, turma_id bigint NOT NULL, materia_id bigint NOT NULL, professor_id bigint, carga_horaria integer NOT NULL);
CREATE TABLE matricula (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, turma_id bigint NOT NULL, aluno_id bigint NOT NULL, dependencia boolean NOT NULL);
CREATE TABLE horario (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, disciplina_id bigint NOT NULL, dia_semana integer NOT NULL, inicio time NOT NULL, fim time NOT NULL);
CREATE TABLE aula (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, disciplina_id bigint NOT NULL, data date NOT NULL, conteudo varchar(4000) NOT NULL, planejamento varchar(4000), horas integer NOT NULL);
CREATE TABLE presenca (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, aula_id bigint NOT NULL, aluno_id bigint NOT NULL, faltas integer NOT NULL);
CREATE TABLE avaliacao (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, disciplina_id bigint NOT NULL, nome varchar(4000) NOT NULL, bimestre integer NOT NULL, valor double precision NOT NULL, data date NOT NULL, tipo varchar(4000) NOT NULL);
CREATE TABLE nota_avaliacao (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, avaliacao_id bigint NOT NULL, aluno_id bigint NOT NULL, valor double precision NOT NULL);
CREATE TABLE nota (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, disciplina_id bigint NOT NULL, aluno_id bigint NOT NULL, bimestre integer NOT NULL, valor double precision, recuperacao double precision, prazo date, liberada boolean NOT NULL);
CREATE TABLE evento (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, titulo varchar(4000) NOT NULL, inicio date NOT NULL, fim date NOT NULL, descricao varchar(4000));
CREATE TABLE mensagem (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, remetente_id bigint NOT NULL, destinatario_id bigint NOT NULL, texto varchar(4000) NOT NULL, enviada_em timestamp);
CREATE TABLE material (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, disciplina_id bigint NOT NULL, nome varchar(4000) NOT NULL, tipo varchar(4000), arquivo varchar(4000), autor_id bigint);
ALTER TABLE pessoa ADD CONSTRAINT pessoa_email_unique UNIQUE(email), ADD CONSTRAINT pessoa_matricula_unique UNIQUE(matricula), ADD CONSTRAINT pessoa_perfil CHECK(perfil IN ('ALUNO','PROFESSOR','SECRETARIA'));
ALTER TABLE matricula ADD CONSTRAINT matricula_unique UNIQUE(turma_id,aluno_id);
ALTER TABLE nota ADD CONSTRAINT nota_unique UNIQUE(disciplina_id,aluno_id,bimestre), ADD CONSTRAINT nota_bimestre CHECK(bimestre BETWEEN 1 AND 4), ADD CONSTRAINT nota_valor CHECK(valor BETWEEN 0 AND 100), ADD CONSTRAINT nota_recuperacao CHECK(recuperacao BETWEEN 0 AND 60);
ALTER TABLE presenca ADD CONSTRAINT presenca_unique UNIQUE(aula_id,aluno_id);
ALTER TABLE nota_avaliacao ADD CONSTRAINT nota_avaliacao_unique UNIQUE(avaliacao_id,aluno_id);
ALTER TABLE turma ADD FOREIGN KEY(curso_id) REFERENCES curso(id), ADD FOREIGN KEY(serie_id) REFERENCES serie(id);
ALTER TABLE curriculo ADD FOREIGN KEY(materia_id) REFERENCES materia(id);
ALTER TABLE disciplina ADD FOREIGN KEY(turma_id) REFERENCES turma(id), ADD FOREIGN KEY(materia_id) REFERENCES materia(id), ADD FOREIGN KEY(professor_id) REFERENCES pessoa(id);
ALTER TABLE matricula ADD FOREIGN KEY(turma_id) REFERENCES turma(id), ADD FOREIGN KEY(aluno_id) REFERENCES pessoa(id);
ALTER TABLE horario ADD FOREIGN KEY(disciplina_id) REFERENCES disciplina(id);
ALTER TABLE aula ADD FOREIGN KEY(disciplina_id) REFERENCES disciplina(id);
ALTER TABLE presenca ADD FOREIGN KEY(aula_id) REFERENCES aula(id), ADD FOREIGN KEY(aluno_id) REFERENCES pessoa(id);
ALTER TABLE avaliacao ADD FOREIGN KEY(disciplina_id) REFERENCES disciplina(id);
ALTER TABLE nota_avaliacao ADD FOREIGN KEY(avaliacao_id) REFERENCES avaliacao(id), ADD FOREIGN KEY(aluno_id) REFERENCES pessoa(id);
ALTER TABLE nota ADD FOREIGN KEY(disciplina_id) REFERENCES disciplina(id), ADD FOREIGN KEY(aluno_id) REFERENCES pessoa(id);
ALTER TABLE mensagem ADD FOREIGN KEY(remetente_id) REFERENCES pessoa(id), ADD FOREIGN KEY(destinatario_id) REFERENCES pessoa(id);
ALTER TABLE material ADD FOREIGN KEY(disciplina_id) REFERENCES disciplina(id), ADD FOREIGN KEY(autor_id) REFERENCES pessoa(id);
CREATE INDEX matricula_aluno ON matricula(aluno_id);
CREATE INDEX disciplina_turma ON disciplina(turma_id);
CREATE INDEX aula_disciplina ON aula(disciplina_id);
